import{na as i}from"./chunk-DDYFOJNZ.js";var r=[{id:1,name:"DrDrakken, auf Amazon.de",text:"Kann dieses Buch zu 100% empfehlen wenn man neu in Angular einsteigen will.",image:"anonymous_m.png",url:"https://www.amazon.de/review/R39TKS3PAXA92J/",date:"2018-07-08",rating:5},{id:2,name:"constructor, auf Amazon.de",text:"Wer Angular von Grund auf lernen m\xF6chte, ist mit dem Buch bestens bedient.",image:"anonymous_m.png",url:"https://www.amazon.de/review/R2LHXE9ESR1IME/",date:"2017-11-30",rating:5},{id:3,name:"J\xF6rg Manske, auf Amazon.de",text:"Tolle Themen. Guter Praxisbezug. Habe den Kauf nicht bereut und w\xFCrde es jederzeit weiterempfehlen.",image:"anonymous_m.png",url:"https://www.amazon.de/review/RGRBABVX6LVT7/",date:"2017-06-21",rating:5},{id:4,name:"schoettner, auf Amazon.de",text:"Eine klare Empfehlung f\xFCr alle, die sich einen \xDCberblick \xFCber moderne SPA-Entwicklung mit Angular verschaffen m\xF6chten.",image:"anonymous_m.png",url:"https://www.amazon.de/review/RZNV11CEQZN9H/",date:"2017-12-11",rating:4},{id:5,name:"Dominik Sprung, auf Amazon.de",text:"Ein Buch, das f\xFCr Einsteiger und Wissenhungrige, empfehlenswert ist.",image:"anonymous_m.png",url:"https://www.amazon.de/review/R2IFSG0B3Y3ENY/",date:"2018-02-22",rating:5},{id:6,name:"Torsten Lehmann, auf Amazon.de",text:"Im Buch wird das Grundkonzept ausf\xFChrlich aber nicht langweilig erkl\xE4rt. [...] Ich gebe wirklich selten 5 Punkte in einer Rezession, hier geht es nicht anders.",image:"anonymous_m.png",url:"https://www.amazon.de/review/R3I0RCWDAR6U0O/",date:"2018-05-01",rating:5},{id:7,name:"F. Salvi, auf Amazon.de",text:"Es macht einfach Spass dieses Buch zu lesen. Ich empfehle es! Die Beispiele sind sehr klar und alles wird sehr gut erkl\xE4rt.",image:"anonymous_m.png",url:"https://www.amazon.de/review/R2HLW0J6P2SVO/",date:"2018-01-24",rating:5},{id:8,name:"Tobias Meier, Lead Softwarearchitekt, BridgingIT GmbH",text:"In meinen Augen hat das Buch gute Chancen, Standardwerk bei der Angular-Ausbildung bei uns zu werden.",image:"tobiasmeier.jpg",date:"2018-12-01",rating:5},{id:9,name:"Jan Buchholz, auf Amazon.de",text:"Der Leser wird von vornherein abgeholt und an die Hand genommen. Alles ist so ausreichend erkl\xE4rt, dass man die Zusammenh\xE4nge verstehen kann und gleichzeitig auch nicht mit zu vielen Infos \xFCberfordert wird.",image:"anonymous_m.png",url:"https://www.amazon.de/review/R2GT6NZP1YY8FQ/",date:"2017-12-03",rating:5},{id:10,name:"Andre Fritzsche, IT Consultant, BridgingIT GmbH",text:"Die Beispiele sind einfach gehalten und gut erkl\xE4rt, so dass man direkt ein gutes Basiswissen aufbaut.",image:"andrefritzsche.jpg",url:"https://www.amazon.de/review/R5Z34MCLHEIHX/",date:"2017-05-30",rating:5},{id:11,name:"Juri Strumpflohner, Blogger und Trainer f\xFCr Angular",text:"It's 500+ pages that get you from beginner to top Angular expert level!",image:"juristrumpflohner.jpg",url:"https://www.linkedin.com/feed/update/urn:li:activity:6278293326827388928",date:"2017-06-15",rating:5,lang:"en"},{id:12,name:"Mireille Puschmann, auf Amazon.de",text:"Die Beispiele sind sehr gut beschrieben, sodass man jeden Schritt nachvollziehen kann. Der Kauf hat sich auf alle F\xE4lle gelohnt.",image:"anonymous_f.png",date:"2018-08-20",rating:5},{id:13,name:"Dr. Jochen Manns, auf Amazon.de",text:"Ich pers\xF6nlich finde den didaktischen Aufbau des Buchs wirklich gelungen. F\xFCr eine Einf\xFChrung ist die Tiefe genau richtig.",image:"anonymous_m.png",url:"https://www.amazon.de/review/R399K09HRVHD6H/",date:"2023-08-14",rating:5},{id:14,name:"Guido K., auf Amazon.de",text:"Das Buch eignet sich hervorragend als Nachschlagewerk, das auf dem Schreibtisch des Angular-Entwicklers nicht fehlen sollte.",image:"anonymous_m.png",url:"https://www.amazon.de/review/R1SOLU9K8RA7YZ/",date:"2017-06-27",rating:5},{id:15,name:"A.B., auf Amazon.de",text:"Das lesen macht wirklich Spa\xDF und es gibt eine gute Lernkurve.",image:"anonymous_m.png",url:"https://www.amazon.de/review/R3NLSJMITWV8DS/",date:"2017-12-19",rating:5},{id:16,name:"Stefan Kert, auf Twitter",text:"Das Warten hat sich gelohnt! Danke f\xFCr dieses geniale Buch!",image:"stefankert.jpg",date:"2017-08-10",rating:5},{id:17,name:"Watzmann, auf Amazon.de",text:"Der Schreibstil ist gut, kein Schaulaufen von Experten, sondern das Vermitteln von Wissen. Ich empfehle das Buch allen, die ingenieursm\xE4\xDFig denken und eine spannende Technologie besser kennenlernen wollen.",image:"anonymous_m.png",url:"https://www.amazon.de/review/R3JWK4ANV77CU8/",date:"2017-06-22",rating:5},{id:18,name:"Anton, auf Amazon.de",text:"Das Buch ist gut strukturiert, das Vorgehen Schritt-f\xFCr-Schritt hilft dabei gut weiter. Die Autoren sind Profis, das erkennt man sofort, und verstehen von ihrem Handwerk.",image:"anonymous_m.png",url:"https://www.amazon.de/review/R23T30POJAVBRB/",date:"2019-05-16",rating:4},{id:19,name:"Leela, auf Amazon.de",text:"Das Buch bietet einen guten ersten Anfang in die Welt von Angular. [...] Ich warte gespannt auf die 2 Version des Buches, um meine aktuellen Projekte umsetzen zu k\xF6nnen.",image:"anonymous_f.png",url:"https://www.amazon.de/review/R2J7SG68MEMORS/",date:"2019-04-01",rating:4},{id:20,name:"Metal King, auf Amazon.de",text:"Ich habe den Eindruck, dass ich hier mit meinem Projekt gut aufgehoben bin. Sehr empfehlenswert!",image:"anonymous_m.png",url:"https://www.amazon.de/review/RWOGARTUT0X4C/",date:"2019-03-30",rating:5},{id:21,name:"ea, auf Amazon.de",text:"Das Buch ist sehr gut strukturiert, sehr gut zu lesen und durch das praktische Beispiel sehr gut zu verinnerlichen.",image:"anonymous_m.png",url:"https://www.amazon.de/review/R1Z7RTKN3E30H8/",date:"2019-01-28",rating:5},{id:22,name:"M.S., auf Amazon.de",text:"Die einzelnen Kapitel sind sehr \xFCbersichtlich strukturiert und man kann den Erl\xE4uterungen zu jeder Zeit gut folgen. Ich kann dieses Buch guten Gewissens jedem empfehlen, der mit Angular zu tun hat. Es ist ein prima Nachschlagewerk.",image:"anonymous_m.png",url:"https://www.amazon.de/review/RF5738OAFT49/",date:"2019-06-25",rating:5},{id:23,name:"C4bb4g3, auf Amazon.de",text:"Das Buch erkl\xE4rt in einem wunderbaren Schreibstil, wie man als Neuling in der Angular-Welt den besten Einstieg bekommt. Man merkt, dass die Autoren sehr tief in der Materie sind und ihr Wissen gerne weitergeben. Somit ist das Buch stets professionell, aber immer nachvollziehbar und verst\xE4ndlich.",image:"anonymous_m.png",url:"https://www.amazon.de/review/R4IRN9CIMBJT3/",date:"2020-07-05",rating:5},{id:24,name:"Klia Maus, auf Amazon.de",text:"Ich bin auf die beiden Autoren durch ein YouTube Video aufmerksam geworden und war gleich begeistert, weil sie so gut und verst\xE4ndlich erkl\xE4ren. Auch das Beispiel, das sich durchzieht, ist sehr gut und hilfreich.",image:"anonymous_f.png",url:"https://www.amazon.de/review/R38XSKCP35DQWH/",date:"2020-04-18",rating:5},{id:25,name:"Johannes Meinhard, auf Amazon.de",text:"Das Buch ist von vorne bis hinten gut strukturiert und alle darin enthaltenen Themen detailliert erkl\xE4rt. Absolute Kaufempfehlung f\xFCr jeden, der sich mit dem Framework Angular bestens vertraut machen m\xF6chte! Ein Lob an die Autoren.",image:"anonymous_m.png",url:"https://www.amazon.de/review/R9MKAABAG85WX/",date:"2020-03-06",rating:5},{id:26,name:"Katharinarrr, auf Amazon.de",text:"Das Buch hat mir sehr gut weiter geholfen und ich w\xFCrde es weiterempfehlen. Der Aufbau sowie Schreibweise des Buchs haben mir gut gefallen, ich hatte beim Lesen nie das Gef\xFChl, nicht folgen zu k\xF6nnen.",image:"anonymous_f.png",url:"https://www.amazon.de/review/R3KBMOD00E8FLW/",date:"2019-11-15",rating:4},{id:27,name:"Matthias Hess, auf Amazon.de",text:"Den kurzweiligen Mix aus Theorie und Praxis empfinde ich als sehr motivierend. Die Autoren k\xF6nnen auch komplexe Themen sehr verst\xE4ndlich erkl\xE4ren. Ich empfehle das Buch jedem, der eine solide Einf\xFChrung ins Thema Angular sucht.",image:"anonymous_m.png",url:"https://www.amazon.de/review/R3NTNKKKDKK8IY/",date:"2019-10-26",rating:5},{id:28,name:"Daniel Ellermann, auf Amazon.de",text:"Es ist sehr sorgf\xE4ltig recherchiert, auf dem neuesten Stand und gibt Einblick in alles, was man von Angular wissen muss. Ich hatte davor schon B\xFCcher von anderen Autoren zu diesem Thema, in diesen wurde jedoch nicht so sauber und anschaulich erkl\xE4rt wie in diesem Buch.",image:"anonymous_m.png",url:"https://www.amazon.de/review/R216WQADV43BSW/",date:"2023-04-16",rating:5},{id:29,name:"OD, auf Amazon.de",text:"Didaktisch eine glatte 1 mit Sternchen! Hervorragend f\xFCr mich als Wirtschaftsinformatiker zum Selbststudium, mit schneller Lernkurve geeignet.",image:"anonymous_m.png",url:"https://www.amazon.de/review/R2VGSXICO52MQ9/",date:"2023-06-27",rating:5},{id:30,name:"Christian P., auf Amazon.de",text:"Insgesamt ein sehr solides und aktuelles Praxisbuch, das sich hervorragend als Nachschlagewerk und als kontinuierliche Lernbegleitung eignet. F\xFCr alle, die Angular professionell einsetzen oder einsetzen wollen, eine klare Empfehlung.",image:"anonymous_m.png",url:"https://www.amazon.de/review/R1ZVH9ICWQY092/",date:"2026-01-11",rating:5},{id:31,name:"Marcus Maack auf LinkedIn",text:"Das erste Angular-Buch von dieser Truppe war meiner Meinung nach das beste auf dem Markt. Allerdings hat sich in #Angular in den letzten 3-5 Jahren so unfassbar viel ver\xE4ndert, dass die drei statt einer 5. Auflage nun ein komplett neues geschrieben haben. Wer Angular (besser) verstehen m\xF6chte, ist hier richtig.",image:"anonymous_m.png",url:"https://www.linkedin.com/posts/marcus-maack-19139718b_angular-activity-7463640301459521537-G0wd?utm_source=share&utm_medium=member_desktop&rcm=ACoAAB5qYsQBQtPwj_1i4cl7qTVpzbjhwavxsY8",date:"2026-05-23",rating:5}];var s={id:"9783988890641",name:"Angular: Das Praxisbuch",description:"Von den Grundlagen bis zur professionellen Entwicklung mit Signals. Das moderne Praxisbuch zu Angular \u2013 ab Version 22",image:"https://angular-buch.com/assets/img/book-cover-v1m.png",price:"39.90",reviews:r.map(n=>({text:n.text,author:n.name,date:n.date,rating:n.rating}))};var u=class n{leseprobeUrl="/assets/angular-buch-leseprobe-auflage1.pdf";getProductLdJson(){return this.#e(s)}#e(e){let a=e.reviews.map(t=>t.rating),d=a.reduce((t,m)=>t+m,0)/a.length;return{sku:e.id,productID:e.id,mpn:e.id,name:e.name,description:e.description,aggregateRating:{reviewCount:a.length,ratingValue:d,"@type":"AggregateRating"},review:e.reviews.map(t=>this.#n(t)),"@type":"Product","@context":"http://schema.org",brand:"Angular-Buch",image:e.image,offers:{"@type":"Offer",priceCurrency:"EUR",price:e.price,priceValidUntil:"2030-12-31T23:59:59",itemCondition:"http://schema.org/NewCondition",availability:"http://schema.org/InStock",url:"https://angular-buch.com/kaufen",shippingDetails:{"@type":"OfferShippingDetails",shippingRate:{"@type":"MonetaryAmount",value:"0",currency:"EUR"},shippingDestination:{"@type":"DefinedRegion",addressCountry:["DE","AT","CH"]},deliveryTime:{"@type":"ShippingDeliveryTime",handlingTime:{"@type":"QuantitativeValue",minValue:0,maxValue:1,unitCode:"DAY"},transitTime:{"@type":"QuantitativeValue",minValue:1,maxValue:3,unitCode:"DAY"}}},hasMerchantReturnPolicy:{"@type":"MerchantReturnPolicy",applicableCountry:["DE","AT","CH"],returnPolicyCategory:"https://schema.org/MerchantReturnFiniteReturnWindow",merchantReturnDays:14,returnMethod:"https://schema.org/ReturnByMail",returnFees:"https://schema.org/FreeReturn"}}}}#n(e){return{reviewRating:{worstRating:"1",ratingValue:e.rating,bestRating:"5","@type":"Rating"},name:e.text,datePublished:e.date,author:{name:e.author,"@type":"Person"},"@type":"Review"}}static \u0275fac=function(a){return new(a||n)};static \u0275prov=i({token:n,factory:n.\u0275fac})};export{r as a,u as b};
